import{_ as n,a0 as d,w as l,s as r,I as a,x as e,a1 as i,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Podman：一個更安全的運行容器的方式 | LCTT x X-CMD","titleTemplate":false,"description":"Podman：一個更安全的運行容器的方式 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Podman：一個更安全的運行容器的方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Podman：一個更安全的運行容器的方式 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20181030 Podman- A more secure way to run containers","title":"Podman：一個更安全的運行容器的方式","tag":"201908","desc":""},"relativePath":"201908/20181030 Podman- A more secure way to run containers.md","filePath":"[post].md"}'),c={name:"201908/20181030 Podman- A more secure way to run containers.md"};function u(h,s,g,k,f,m){const o=d("Link");return l(),r("div",null,[s[18]||(s[18]=a("h1",{id:"podman-一個更安全的運行容器的方式",tabindex:"-1"},[e("Podman：一個更安全的運行容器的方式 "),a("a",{class:"header-anchor",href:"#podman-一個更安全的運行容器的方式","aria-label":"Permalink to “Podman：一個更安全的運行容器的方式”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"Podman 使用傳統的 fork/exec 模型（相對於客户端/服務器模型）來運行容器。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/23/234924m55sn8zt3b5q8815.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在進入本文的主要主題 ",-1)),i(o,{href:"https://podman.io"},{default:t(()=>[...s[0]||(s[0]=[e("Podman",-1)])]),_:1}),s[2]||(s[2]=e(" 和容器之前，我需要了解一點 Linux 審計功能的技術。",-1))]),s[21]||(s[21]=p(`<h3 id="什麼是審計" tabindex="-1">什麼是審計？ <a class="header-anchor" href="#什麼是審計" aria-label="Permalink to “什麼是審計？”">​</a></h3><p>Linux 內核有一個有趣的安全功能，叫做<strong>審計</strong>。它允許管理員在系統上監視安全事件，並將它們記錄到<code>audit.log</code> 中，該文件可以本地存儲或遠程存儲在另一台機器上，以防止黑客試圖掩蓋他的蹤跡。</p><p><code>/etc/shadow</code> 文件是一個經常要監控的安全文件，因為向其添加記錄可能允許攻擊者獲得對系統的訪問權限。管理員想知道是否有任何進程修改了該文件，你可以通過執行以下命令來執行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># auditctl -w /etc/shadow</span></span></code></pre></div><p>現在讓我們看看當我修改了 <code>/etc/shadow</code> 文件會發生什麼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /etc/shadow </span></span>
<span class="line"><span># ausearch -f /etc/shadow -i -ts recent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type=PROCTITLE msg=audit(10/10/2018 09:46:03.042:4108) : proctitle=touch /etc/shadow type=SYSCALL msg=audit(10/10/2018 09:46:03.042:4108) : arch=x86_64 syscall=openat success=yes exit=3 a0=0xffffff9c a1=0x7ffdb17f6704 a2=O_WRONLY|O_CREAT|O_NOCTTY| O_NONBLOCK a3=0x1b6 items=2 ppid=2712 pid=3727 auid=dwalsh uid=root gid=root euid=root suid=root fsuid=root egid=root sgid=root fsgid=root tty=pts1 ses=3 comm=touch exe=/usr/bin/touch subj=unconfined_u:unconfined_r:unconfined_t:s0-s0:c0.c1023 key=(null)\`</span></span></code></pre></div><p>審計記錄中有很多信息，但我重點注意到它記錄了 root 修改了 <code>/etc/shadow</code> 文件，並且該進程的審計 UID（<code>auid</code>）的所有者是 <code>dwalsh</code>。</p><p>內核修改了這個文件了麼？</p><h4 id="跟蹤登錄-uid" tabindex="-1">跟蹤登錄 UID <a class="header-anchor" href="#跟蹤登錄-uid" aria-label="Permalink to “跟蹤登錄 UID”">​</a></h4><p>登錄 UID（<code>loginuid</code>），存儲在 <code>/proc/self/loginuid</code> 中，它是系統上每個進程的 proc 結構的一部分。該字段只能設置一次；設置後，內核將不允許任何進程重置它。</p><p>當我登錄系統時，登錄程序會為我的登錄過程設置 <code>loginuid</code> 字段。</p><p>我（<code>dwalsh</code>）的 UID 是 3267。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/self/loginuid</span></span>
<span class="line"><span>3267</span></span></code></pre></div><p>現在，即使我變成了 root，我的登錄 UID 仍將保持不變。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cat /proc/self/loginuid</span></span>
<span class="line"><span>3267</span></span></code></pre></div><p>請注意，從初始登錄過程 fork 並 exec 的每個進程都會自動繼承 <code>loginuid</code>。這就是內核知道登錄的人是 <code>dwalsh</code> 的方式。</p><h3 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to “容器”">​</a></h3><p>現在讓我們來看看容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo podman run fedora cat /proc/self/loginuid</span></span>
<span class="line"><span>3267</span></span></code></pre></div><p>甚至容器進程也保留了我的 <code>loginuid</code>。 現在讓我們用 Docker 試試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo docker run fedora cat /proc/self/loginuid </span></span>
<span class="line"><span>4294967295</span></span></code></pre></div><h3 id="為什麼不一樣" tabindex="-1">為什麼不一樣？ <a class="header-anchor" href="#為什麼不一樣" aria-label="Permalink to “為什麼不一樣？”">​</a></h3><p>Podman 對於容器使用傳統的 fork/exec 模型，因此容器進程是 Podman 進程的後代。Docker 使用客户端/服務器模型。我執行的 <code>docker</code> 命令是 Docker 客户端工具，它通過客户端/服務器操作與 Docker 守護進程通信。然後 Docker 守護程序創建容器並處理 stdin/stdout 與 Docker 客户端工具的通信。</p><p>進程的默認 <code>loginuid</code>（在設置 <code>loginuid</code> 之前）是 <code>4294967295</code>（LCTT 譯註：2^32 - 1）。由於容器是 Docker 守護程序的後代，而 Docker 守護程序是 init 系統的子代，所以，我們看到 systemd、Docker 守護程序和容器進程全部具有相同的 <code>loginuid</code>：<code>4294967295</code>，審計系統視其為未設置審計 UID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /proc/1/loginuid </span></span>
<span class="line"><span>4294967295</span></span></code></pre></div><h3 id="怎麼會被濫用" tabindex="-1">怎麼會被濫用？ <a class="header-anchor" href="#怎麼會被濫用" aria-label="Permalink to “怎麼會被濫用？”">​</a></h3><p>讓我們來看看如果 Docker 啓動的容器進程修改 <code>/etc/shadow</code> 文件會發生什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run --privileged -v /:/host fedora touch /host/etc/shadow </span></span>
<span class="line"><span>$ sudo ausearch -f /etc/shadow -i type=PROCTITLE msg=audit(10/10/2018 10:27:20.055:4569) : proctitle=/usr/bin/coreutils --coreutils-prog-shebang=touch /usr/bin/touch /host/etc/shadow type=SYSCALL msg=audit(10/10/2018 10:27:20.055:4569) : arch=x86_64 syscall=openat success=yes exit=3 a0=0xffffff9c a1=0x7ffdb6973f50 a2=O_WRONLY|O_CREAT|O_NOCTTY| O_NONBLOCK a3=0x1b6 items=2 ppid=11863 pid=11882 auid=unset uid=root gid=root euid=root suid=root fsuid=root egid=root sgid=root fsgid=root tty=(none) ses=unset comm=touch exe=/usr/bin/coreutils subj=system_u:system_r:spc_t:s0 key=(null)</span></span></code></pre></div><p>在 Docker 情形中，<code>auid</code> 是未設置的（<code>4294967295</code>）；這意味着安全人員可能知道有進程修改了 <code>/etc/shadow</code> 文件但身份丟失了。</p><p>如果該攻擊者隨後刪除了 Docker 容器，那麼在系統上誰修改 <code>/etc/shadow</code> 文件將沒有任何跟蹤信息。</p><p>現在讓我們看看相同的場景在 Podman 下的情況。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo podman run --privileged -v /:/host fedora touch /host/etc/shadow </span></span>
<span class="line"><span>$ sudo ausearch -f /etc/shadow -i type=PROCTITLE msg=audit(10/10/2018 10:23:41.659:4530) : proctitle=/usr/bin/coreutils --coreutils-prog-shebang=touch /usr/bin/touch /host/etc/shadow type=SYSCALL msg=audit(10/10/2018 10:23:41.659:4530) : arch=x86_64 syscall=openat success=yes exit=3 a0=0xffffff9c a1=0x7fffdffd0f34 a2=O_WRONLY|O_CREAT|O_NOCTTY| O_NONBLOCK a3=0x1b6 items=2 ppid=11671 pid=11683 auid=dwalsh uid=root gid=root euid=root suid=root fsuid=root egid=root sgid=root fsgid=root tty=(none) ses=3 comm=touch exe=/usr/bin/coreutils subj=unconfined_u:system_r:spc_t:s0 key=(null)</span></span></code></pre></div><p>由於它使用傳統的 fork/exec 方式，因此 Podman 正確記錄了所有內容。</p><p>這只是觀察 <code>/etc/shadow</code> 文件的一個簡單示例，但審計系統對於觀察系統上的進程非常有用。使用 fork/exec 容器運行時（而不是客户端/服務器容器運行時）來啓動容器允許你通過審計日誌記錄保持更好的安全性。</p><h3 id="最後的想法" tabindex="-1">最後的想法 <a class="header-anchor" href="#最後的想法" aria-label="Permalink to “最後的想法”">​</a></h3><p>在啓動容器時，與客户端/服務器模型相比，fork/exec 模型還有許多其他不錯的功能。例如，systemd 功能包括：</p><ul><li><code>SD_NOTIFY</code>：如果將 Podman 命令放入 systemd 單元文件中，容器進程可以通過 Podman 返回通知，表明服務已準備好接收任務。這是在客户端/服務器模式下無法完成的事情。</li><li>套接字激活：你可以將連接的套接字從 systemd 傳遞到 Podman，並傳遞到容器進程以便使用它們。這在客户端/服務器模型中是不可能的。</li></ul><p>在我看來，其最好的功能是<strong>作為非 root 用户運行 Podman 和容器</strong>。這意味着你永遠不會在宿主機上授予用户 root 權限，而在客户端/服務器模型中（如 Docker 使用的），你必須打開以 root 身份運行的特權守護程序的套接字來啓動容器。在那裏，你將受到守護程序中實現的安全機制與宿主機操作系統中實現的安全機制的支配 —— 這是一個危險的主張。</p><hr>`,39)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),i(o,{href:"https://opensource.com/article/18/10/podman-more-secure-way-run-containers"},{default:t(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/18/10/podman-more-secure-way-run-containers",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=e("作者：",-1)),i(o,{href:"https://opensource.com/users/rhatdan"},{default:t(()=>[...s[5]||(s[5]=[e("Daniel J Walsh",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const C=n(c,[["render",u]]);export{x as __pageData,C as default};
